obs = {
  const edificio = estructura.startsWith("Edificio");
  const e = edificio ? edificioCortante([2e5, 2e5, 2e5], [5e7, 5e7, 4e7])
                     : {M: [[1, 0, 0], [0, 1, 0], [0, 0, 1]], K: [[2, -1, 0], [-1, 2, -1], [0, -1, 2]]};
  const mod = {...e, ...modosPropios(e.K, e.M)};
  const n = 3, m = e.M[0][0];
  const w0 = 2 * Math.PI * mod.f[0];
  // tiempo normalizado τ = ω₁ t y estado [q; q'/ω₁]: A = [[0, I], [-M⁻¹K/ω₁², 0]]
  const Kn = e.K.map((f) =&gt; f.map((v) =&gt; v / (m * w0 * w0)));
  const A = [...Array(2 * n)].map((_, i) =&gt; [...Array(2 * n)].map((_, j) =&gt;
    i &lt; n ? (j === i + n ? 1 : 0) : (j &lt; n ? -Kn[i - n][j] : 0)));
  const filaC = (s) =&gt; {
    const fila = new Array(2 * n).fill(0);
    if (magnitud === "desplazamiento") fila[s] = 1;
    else if (magnitud === "velocidad") fila[n + s] = 1;
    else for (let j = 0; j &lt; n; j++) fila[j] = -Kn[s][j];     // aceleración = -M⁻¹K q (sin amortiguamiento)
    return fila;
  };
  const C = sensores.map((s) =&gt; filaC(s - 1));
  let O = [], P = C;
  for (let k = 0; k &lt; 2 * n && C.length &gt; 0; k++) { O = O.concat(P); P = matMul(P, A); }
  const r = C.length ? rango(O, 1e-9 * Math.max(...O.flat().map(Math.abs))) : 0;
  // visibilidad modal: tamaño de C φ_k con los modos normalizados a masa unidad, adimensionalizado con √m
  const vis = [0, 1, 2].map((k) =&gt; Math.sqrt(sensores.reduce((s, i) =&gt; s + (mod.Phi[i - 1][k] * Math.sqrt(m)) ** 2, 0)));
  return {mod, r, vis, n};
}









